def monthly_candidates() -> set[str]:
    text = (ROOT / "Scripts" / "MonthlyCatalog.gd").read_text(encoding="utf-8")
    result: set[str] = set()
    for match in __import__("re").finditer(r'"((?:[^"\\]|\\.)*)"', text):
        value = match.group(1).replace(r"\n", "\n")
        if not any(char.isalpha() for char in value):
            continue
        if value.startswith(("res://", "http", "uid://", "#")):
            continue
        if __import__("re").fullmatch(r"[a-z0-9_./:-]+", value):
            continue
        result.add(value)
    return result


def translate_monthly(value: str) -> str:
    if value in MONTHLY_EXACT:
        return MONTHLY_EXACT[value]
    translated = value
    for portuguese, english in TERM_REPLACEMENTS:
        translated = translated.replace(portuguese, english)
    return translated


def main() -> None:
    with CATALOGO.open(encoding="utf-8", newline="") as arquivo:
        rows = list(csv.reader(arquivo))
    by_key = {row[0]: row for row in rows[1:] if row}
    for key in OBSOLETE_KEYS:
        by_key.pop(key, None)
    for key, (pt, en) in TRANSLATIONS.items():
        by_key[key] = [key, pt, en]
    untranslated_monthly: list[str] = []
    for key in monthly_candidates():
        english = translate_monthly(key)
        if key in MONTHLY_EXACT:
            by_key[key] = [key, key, english]
            TRANSLATIONS[key] = (key, english)
            continue
        # Nunca substitui uma tradução humana já registrada no dicionário
        # principal. O glossário abaixo existe apenas para selos e títulos
        # curtos do calendário, não para reescrever textos narrativos.
        if key in TRANSLATIONS:
            continue
        if english != key:
            by_key[key] = [key, key, english]
            TRANSLATIONS[key] = (key, english)
            continue
        if key in by_key:
            continue
        if english == key and key not in MONTHLY_EXACT:
            untranslated_monthly.append(key)
            continue
    if untranslated_monthly:
        raise RuntimeError("Textos Monthly sem tradução: " + repr(sorted(untranslated_monthly)))
    ordered = [rows[0]]
    seen: set[str] = set()
    for row in rows[1:]:
        if row and row[0] in by_key and row[0] not in seen:
            ordered.append(by_key[row[0]])
            seen.add(row[0])
    for key in TRANSLATIONS:
        if key not in seen:
            ordered.append(by_key[key])
    with CATALOGO.open("w", encoding="utf-8", newline="") as arquivo:
        csv.writer(arquivo, lineterminator="\n").writerows(ordered)


if __name__ == "__main__":
    main()
